import{z as E,x as s,o as t,c as p,q as i,j as l,D as e,d as o,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"标准单元与轨道高度","description":"","frontmatter":{"title":"标准单元与轨道高度","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/standard-cell-track-height.md","filePath":"litho/standard-cell-track-height.md","lastUpdated":1791063341000}'),d={name:"litho/standard-cell-track-height.md"};function h(T,a,D,c,m,B){const r=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="标准单元与轨道高度" tabindex="-1">标准单元与轨道高度 <a class="header-anchor" href="#标准单元与轨道高度" aria-label="Permalink to &quot;标准单元与轨道高度&quot;">​</a></h1><div class="epigraph"><p>轨道高度是标准单元的纵向节拍：它把金属节距、电源轨和可印取向收成一个整数，密度与可布线性在此对赌。</p><footer>—— 对照 imec DTCO 对 track height、FinFlex 与布线网格的公开论述</footer></div><p><a href="/litho/min-area-tip-to-tip">上一课</a>把 tip 与面积写成独立条款。缺口是单元：逻辑库用几条金属轨高，直接决定有多少 tip、多少 via、电源是否挤在不可印的缝里。<a href="/litho/dtco-patterning">DTCO</a> 已点名轨道；本课钉图形化侧如何选轨高。缩放助推器（接触上栅、埋入电源等）留给<a href="/litho/scaling-boosters">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准单元高度常以金属 2（或中间层）轨道数计：6T、7.5T、5T 一类。轨少则密度高，但电源、信号、扩散接触争同一套 tip-to-tip 与 via 覆盖预算；轨多则好布、好印，面积涨。Fin/nanosheet 的器件宽度分档（FinFlex 一类）让同一轨高下 drive 可变，但布线通道数仍被轨高锁死。</p>',5)),(t(),l(A,null,{default:e(()=>[n(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BD%A8%E9%AB%98%E9%80%89%E5%87%A0%E6%9D%A1%E8%BD%A8%3F%22%5D%20--%3E%20LOW%5B%22%E5%B0%91%E8%BD%A8%3A%205T%20%2F%206T%22%5D%0A%20%20Q%20--%3E%20HIGH%5B%22%E5%A4%9A%E8%BD%A8%3A%207.5T%20%2F%209T%22%5D%0A%20%20LOW%20--%3E%20DEN%5B%22%E9%9D%A2%E7%A7%AF%E5%B0%8F%20%E5%AF%86%E5%BA%A6%E9%AB%98%22%5D%0A%20%20LOW%20--%3E%20RISK%5B%22tip%20%E5%AF%B9%E6%92%9E%20%2F%20via%20%E8%A6%86%E7%9B%96%E5%90%83%E7%B4%A7%22%5D%0A%20%20HIGH%20--%3E%20SAFE%5B%22%E5%A5%BD%E5%B8%83%E7%BA%BF%20%E5%8F%AF%E5%8D%B0%E6%80%A7%E5%A5%BD%22%5D%0A%20%20HIGH%20--%3E%20AREA%5B%22%E9%9D%A2%E7%A7%AF%E6%B6%A8%22%5D%0A%20%20RISK%20--%3E%20DTCO%5B%22DTCO%20%E7%94%A8%E4%BB%A3%E8%A1%A8%E5%8D%95%E5%85%83%E6%8A%95%E7%A5%A8%22%5D%0A%20%20AREA%20--%3E%20DTCO%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>缺口是<strong>轨高作为光刻约束的整数</strong>，不是重讲标准单元电路。把轨高当纯设计风格，会忽略：单向金属加切线、EUV 单次对二维 jog 的容忍、以及电源轨 CD 对电迁徙的可靠性规则。</p><p><span class="marginnote">「轨」翻译成图书馆的书架：单元高度就是给布线留几层书架。书架少（5T）书塞得挤、密度高，但两本书顶头相撞（tip 对撞）的概率大增；书架多（7.5T、9T）好放书、好印，占地却变大。轨高就是这场交易签下的整数合同。</span></p><h3 id="半轨与奇数轨" tabindex="-1">半轨与奇数轨 <a class="header-anchor" href="#半轨与奇数轨" aria-label="Permalink to &quot;半轨与奇数轨&quot;">​</a></h3><p>非整数轨（7.5T）来自器件与金属网格不对齐或电源轨加倍。半轨让布线灵活，却制造更多不规则 tip 与着色困难。LFD 必须对整库、而不是只对 inverter 跑前向。奇数轨对镜像单元和电源网格的周期性不友好，填充与刻蚀密度也会破周期。</p><p><span class="marginnote">数字实例：金属节距 40 nm 时，6T 单元高 \\(6 \\times 40 = 240\\) nm，7.5T 就是 300 nm——每个单元多出 60 nm，一百万个单元的宏就多出 60 mm 的总高度账。半轨的灵活性是用这种成片的面积代价换的。</span></p><p><span class="marginnote">单元库 freeze 等于冻结该层最密、最二维的 clips。OPC 模型的保持集应含库，而不是只含逻辑随机布线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>候选轨高 × 金属节距 × 分解选项 → 代表单元（逆变器、触发器、多指）跑 SMO/OPC/PV 与 via 覆盖。看：热点数、切线需求、电源轨窗口、可布线性（销钉是否够）。与 <a href="/litho/cpp-mmp">CPP/MMP</a> 后课（路线图门）的关系：本课只问图形化可实现；晶体管密度数字留给节点命名课序。High-NA 半场是否逼大核改芯粒，是 DTCO 面积，本课只要求轨高评估包含拼接假设。</p><p>触发器和多位加法器比 inverter 更吃 tip 与 via 色。轨高评估集必须含这些，否则 6T 库在 inverter 上绿灯、在时序单元上红。imec 公开 DTCO 叙述正是用代表单元族，而不是单一标准单元。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>轨高 \\(H = N \\times\\) 金属节距（加电源特例）。\\(N\\) 下降，信号轨变少，布线器更常制造 tip 对撞和错误 via 颜色。光学上，密且重复的单元是周期结构，RCWA/紧凑核都较稳；一旦半轨破坏周期性，全芯片匹配库必须增收非周期 clips。电源轨往往是最宽、最敏感的 CD，刻蚀负载与它的开口率绑定。</p>',11)),(t(),l(A,null,{default:e(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E8%BD%A8%E6%95%B0%20N%22%5D%20--%3E%20PITCH%5B%22%E9%87%91%E5%B1%9E%E8%8A%82%E8%B7%9D%22%5D%0A%20%20N%20--%3E%20T2T%5B%22tip%20%2F%20via%20%E5%AF%86%E5%BA%A6%22%5D%0A%20%20PITCH%20--%3E%20PRINT%5B%22%E5%8F%AF%E5%8D%B0%E6%80%A7%20%2F%20%E5%88%86%E8%A7%A3%22%5D%0A%20%20T2T%20--%3E%20PRINT%0A%20%20PRINT%20--%3E%20LIB%5B%22%E5%BA%93%20freeze%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p>轨数下降时，图中 tip/via 密度先于金属节距成为可印瓶颈。库 freeze 要把这条路径写进保持集，而不是只交节距表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某代工厂未公开的轨高表当规范。不重写 FinFET/GAA 静电学。轨高选择含电学与时序，本课只交付图形化可行集。</p><p>后课默认：库轨高是已冻结的光刻约束。下一课看埋入电源、接触上栅一类助推器如何在不无限减轨的前提下再挤密度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>轨道高度把金属节距与单元纵向通道收成整数，是 DTCO 的图形化旋钮。</li><li>少轨提高 tip/via 风险；半轨破坏周期与着色。</li><li>库必须进 OPC 保持集。</li><li>出处：imec DTCO 对 track height 的公开论述；标准单元与可印网格通称。</li></ul>',6))])}const C=E(d,[["render",h]]);export{f as __pageData,C as default};
